-- Колія: перенос переводов из i18n.js в базу. Выполнить один раз в Supabase → SQL Editor.
-- Скрипт можно запускать повторно: уже заполненные значения не перезаписываются.

-- 1. Тексты интерфейса: одна строка на ключ, колонка на язык
create table if not exists ui_texts (
  key text primary key,
  ru text not null default '',
  uk text not null default '',
  en text not null default '',
  pl text not null default '',
  updated_at timestamptz not null default now()
);
alter table ui_texts enable row level security;
drop policy if exists ui_texts_read on ui_texts;
create policy ui_texts_read on ui_texts for select to anon, authenticated using (true);
drop policy if exists ui_texts_write on ui_texts;
create policy ui_texts_write on ui_texts for all to authenticated using (true) with check (true);

insert into ui_texts (key, ru, uk, en, pl)
select k, coalesce(v->>'ru', ''), coalesce(v->>'uk', ''), coalesce(v->>'en', ''), coalesce(v->>'pl', '')
from jsonb_each($j${"h":{"ru":"ч","uk":"год","en":"h","pl":"godz."},"min":{"ru":"мин","uk":"хв","en":"min","pl":"min"},"tag0":{"ru":"без пересадок","uk":"без пересадок","en":"direct","pl":"bez przesiadek"},"tag1":{"ru":"1 пересадка","uk":"1 пересадка","en":"1 transfer","pl":"1 przesiadka"},"tag2":{"ru":"{n} пересадки","uk":"{n} пересадки","en":"{n} transfers","pl":"{n} przesiadki"},"tag5":{"ru":"{n} пересадок","uk":"{n} пересадок","en":"{n} transfers","pl":"{n} przesiadek"},"loc":{"ru":"Время местное","uk":"Час місцевий","en":"Local time","pl":"Czas lokalny"},"seat":{"ru":"Сидячий интерсити","uk":"Сидячий інтерсіті","en":"Seated InterCity","pl":"InterCity, miejsca siedzące"},"odd":{"ru":"Ходит по нечётным числам","uk":"Курсує за непарними числами","en":"Runs on odd-numbered dates","pl":"Kursuje w nieparzyste dni"},"even":{"ru":"Ходит по чётным числам","uk":"Курсує за парними числами","en":"Runs on even-numbered dates","pl":"Kursuje w parzyste dni"},"train":{"ru":"Поезд","uk":"Поїзд","en":"Train","pl":"Pociąg"},"no":{"ru":"№","uk":"№","en":"No. ","pl":"nr "},"swap":{"ru":"Пересадка: {a}","uk":"Пересадка: {a}","en":"Transfer: {a}","pl":"Przesiadka: {a}"},"swapIn":{"ru":"Пересадка {c}","uk":"Пересадка {c}","en":"Transfer {c}","pl":"Przesiadka {c}"},"swapArr":{"ru":"Пересадка: {a} → {b}","uk":"Пересадка: {a} → {b}","en":"Transfer: {a} → {b}","pl":"Przesiadka: {a} → {b}"},"f1":{"ru":"Справочник железнодорожных маршрутов из Украины и в Украину. Расписания, станции, пересадки и полезная информация для пассажиров.","uk":"Довідник залізничних маршрутів з України та в Україну. Розклади, станції, пересадки та корисна інформація для пасажирів.","en":"A guide to rail routes from and to Ukraine: timetables, stations, transfers and useful information for passengers.","pl":"Przewodnik po trasach kolejowych z Ukrainy i do Ukrainy: rozkłady jazdy, stacje, przesiadki i przydatne informacje dla pasażerów."},"f2h":{"ru":"Актуальность информации","uk":"Актуальність інформації","en":"Keeping information up to date","pl":"Aktualność informacji"},"f2a":{"ru":"Расписание поездов, время отправления и прибытия могут изменяться. Перед поездкой проверяйте актуальную информацию на сайтах перевозчиков.","uk":"Розклад поїздів, час відправлення та прибуття можуть змінюватися. Перед поїздкою перевіряйте актуальну інформацію на сайтах перевізників.","en":"Train timetables and departure and arrival times may change. Before you travel, check current information on the carriers’ websites.","pl":"Rozkłady jazdy oraz godziny odjazdów i przyjazdów mogą ulec zmianie. Przed podróżą sprawdź aktualne informacje na stronach przewoźników."},"f2b":{"ru":"Информация на странице обновлена: 01.11.2026.","uk":"Інформацію на сторінці оновлено: 01.11.2026.","en":"Page last updated: 01.11.2026.","pl":"Informacje na stronie zaktualizowano: 01.11.2026."},"f2c":{"ru":"«Колія» — независимый информационный проект, не связанный с АО «Укрзализныця».","uk":"«Колія» — незалежний інформаційний проєкт, не пов’язаний з АТ «Укрзалізниця».","en":"Koliya is an independent information project and is not affiliated with JSC Ukrzaliznytsia.","pl":"„Koliya” to niezależny projekt informacyjny, niezwiązany z JSC Ukrzaliznytsia."},"f3h":{"ru":"Справочная служба Укрзализныци","uk":"Довідкова служба Укрзалізниці","en":"Ukrzaliznytsia information line","pl":"Infolinia Ukrzaliznyci"},"f3":{"ru":"0 800 503 111 · 044 465 33 44<br>Звонки на номер 0 800 бесплатны с украинских номеров.","uk":"0 800 503 111 · 044 465 33 44<br>Дзвінки на номер 0 800 безкоштовні з українських номерів.","en":"0 800 503 111 · 044 465 33 44<br>Calls to 0 800 are free from Ukrainian numbers.","pl":"0 800 503 111 · 044 465 33 44<br>Połączenia na numer 0 800 są bezpłatne z numerów ukraińskich."},"fsrc":{"ru":"Источник данных о поездах:","uk":"Джерело даних про поїзди:","en":"Train data sources:","pl":"Źródła danych o pociągach:"},"back.home":{"ru":"← Главная","uk":"← Головна","en":"← Home","pl":"← Strona główna"},"direct.h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"direct.s":{"ru":"без пересадок","uk":"без пересадок","en":"no transfers","pl":"bez przesiadek"},"transfer.h":{"ru":"С удобной пересадкой в Хелме на одной платформе","uk":"Зручна пересадка в Хелмі на одній платформі","en":"With a convenient same-platform transfer in Chełm","pl":"Z wygodną przesiadką w Chełmie na jednym peronie"},"coach":{"ru":"В купе предусмотрены три спальных места, расположенные одно над другим. Если средняя полка приведена в спальное положение, пользоваться нижней полкой для сидения нельзя. Для подъёма на верхнюю полку предусмотрена лестница.","uk":"У купе передбачено три спальні місця, розташовані одне над одним. Якщо середню полицю переведено у спальне положення, сидіти на нижній полиці не можна. Для підйому на верхню полицю передбачено драбину.","en":"Each compartment has three berths, one above another. When the middle berth is folded down for sleeping, the lower berth cannot be used for sitting. A ladder is provided for climbing to the upper berth.","pl":"W przedziale są trzy miejsca do spania, jedno nad drugim. Gdy środkowa półka jest rozłożona do spania, nie wolno siedzieć na dolnej. Na górną półkę prowadzi drabinka."},"noopts.h":{"ru":"Пока нет вариантов","uk":"Поки що немає варіантів","en":"No options yet","pl":"Brak połączeń"},"noopts.p":{"ru":"Добавьте их в админке.","uk":"Додайте їх в адмінці.","en":"Add them in the admin panel.","pl":"Dodaj je w panelu administratora."},"err.h":{"ru":"Не удалось загрузить данные","uk":"Не вдалося завантажити дані","en":"Could not load the data","pl":"Nie udało się załadować danych"},"err.p":{"ru":"Обновите страницу позже.","uk":"Оновіть сторінку пізніше.","en":"Please refresh the page later.","pl":"Odśwież stronę później."},"loading":{"ru":"Загрузка…","uk":"Завантаження…","en":"Loading…","pl":"Ładowanie…"},"d.more":{"ru":"Подробнее","uk":"Докладніше","en":"Details","pl":"Szczegóły"},"d.less":{"ru":"Свернуть","uk":"Згорнути","en":"Collapse","pl":"Zwiń"},"d.nochg":{"ru":"Без пересадок","uk":"Без пересадок","en":"No transfers","pl":"Bez przesiadek"},"d.checked":{"ru":"Проверено:","uk":"Перевірено:","en":"Checked:","pl":"Sprawdzono:"},"d.daily":{"ru":"Ежедневно","uk":"Щодня","en":"Daily","pl":"Codziennie"},"d.odd":{"ru":"По нечётным дням","uk":"По непарних днях","en":"On odd dates","pl":"W dni nieparzyste"},"d.even":{"ru":"По чётным дням","uk":"По парних днях","en":"On even dates","pl":"W dni parzyste"},"d.howq":{"ru":"Как купить билеты?","uk":"Як купити квитки?","en":"How to buy tickets?","pl":"Jak kupić bilety?"},"d.hows":{"ru":"Подробная инструкция для каждого варианта маршрута.","uk":"Докладна інструкція для кожного варіанта маршруту.","en":"Step-by-step instructions for each route option.","pl":"Szczegółowa instrukcja dla każdego wariantu trasy."},"d.how":{"ru":"Инструкция","uk":"Інструкція","en":"Instructions","pl":"Instrukcja"},"more.h":{"ru":"Ещё маршруты","uk":"Інші маршрути","en":"More routes","pl":"Inne trasy"},"more.all":{"ru":"Все страны","uk":"Усі країни","en":"All countries","pl":"Wszystkie kraje"},"buy.h":{"ru":"Как купить билеты","uk":"Як купити квитки","en":"How to buy tickets","pl":"Jak kupić bilety"},"buy.d.h":{"ru":"Прямой поезд","uk":"Прямий поїзд","en":"Direct train","pl":"Pociąg bezpośredni"},"buy.s1":{"ru":"Откройте приложение «Укрзалізниця» и войдите в свою учётную запись.","uk":"Відкрийте застосунок «Укрзалізниця» та увійдіть у свій обліковий запис.","en":"Open the Ukrzaliznytsia app and sign in to your account.","pl":"Otwórz aplikację Ukrzaliznytsia i zaloguj się na swoje konto."},"buy.d.s2":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {dir} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Билеты на прямой поезд пользуются высоким спросом, поэтому рекомендуем покупать их сразу после начала продаж.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {dir} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. На прямий поїзд квитки користуються великим попитом, тому радимо купувати їх одразу після початку продажу.","en":"Open the Ukrzaliznytsia app, choose the route {dir} and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Tickets for the direct train are in high demand, so we recommend buying them as soon as sales open.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {dir} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Bilety na pociąg bezpośredni cieszą się dużym popytem, dlatego warto kupić je zaraz po otwarciu sprzedaży."},"buy.d.s3":{"ru":"Выберите место в купейном вагоне стандарта RIC и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце в купейному вагоні стандарту RIC і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a berth in an RIC-standard compartment car and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce w wagonie z przedziałami standardu RIC i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."},"buy.d.btn":{"ru":"Купить в приложении УЗ билет {dir}","uk":"Купити в застосунку УЗ квиток {dir}","en":"Buy the {dir} ticket in the UZ app","pl":"Kup w aplikacji UZ bilet {dir}"},"buy.t.h":{"ru":"С пересадкой {xin}","uk":"З пересадкою {xin}","en":"With a transfer {xin}","pl":"Z przesiadką {xin}"},"buy.t.s1":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {uz} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {uz} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {uz} and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {uz} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},"buy.t.s1one":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {uz} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени. Выберите поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {uz} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом. Оберіть поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {uz} and the travel date. Sales open 20 days before departure at 09:00 Kyiv time. Choose the train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {uz} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego. Wybierz pociąg i opłać bilet."},"buy.t.s2":{"ru":"Билет на поезд {pkp} приобретите отдельно у польского перевозчика PKP Intercity — на официальном сайте intercity.pl или в приложении PKP Intercity. Также билеты можно приобрести на сайте koleo.pl или в приложении KOLEO.","uk":"Квиток на поїзд {pkp} придбайте окремо в польського перевізника PKP Intercity — на офіційному сайті intercity.pl або в застосунку PKP Intercity. Також квитки можна купити на сайті koleo.pl або в застосунку KOLEO.","en":"Buy the {pkp} ticket separately from the Polish carrier PKP Intercity, on intercity.pl or in the PKP Intercity app. You can also buy it on koleo.pl or in the KOLEO app.","pl":"Bilet na pociąg {pkp} kup osobno u polskiego przewoźnika PKP Intercity — na stronie intercity.pl lub w aplikacji PKP Intercity. Można go też kupić na koleo.pl lub w aplikacji KOLEO."},"buy.t3out":{"ru":"При выборе поезда {pkp} ориентируйтесь на варианты и расписание, представленные выше на этой странице. Учитывайте время прибытия поезда {uz} и продолжительность пересадки.","uk":"Обираючи поїзд {pkp}, орієнтуйтеся на варіанти та розклад, наведені вище на цій сторінці. Зважайте на час прибуття поїзда {uz} і тривалість пересадки.","en":"When choosing the {pkp} train, use the options and timetable shown above on this page. Allow for the arrival time of the {uz} train and the length of the transfer.","pl":"Wybierając pociąg {pkp}, kieruj się wariantami i rozkładem podanymi wyżej na tej stronie. Uwzględnij godzinę przyjazdu pociągu {uz} i czas przesiadki."},"buy.t3in":{"ru":"При выборе поезда {pkp} ориентируйтесь на варианты и расписание, представленные выше на этой странице. Учитывайте время отправления поезда {uz} и продолжительность пересадки.","uk":"Обираючи поїзд {pkp}, орієнтуйтеся на варіанти та розклад, наведені вище на цій сторінці. Зважайте на час відправлення поїзда {uz} і тривалість пересадки.","en":"When choosing the {pkp} train, use the options and timetable shown above on this page. Allow for the departure time of the {uz} train and the length of the transfer.","pl":"Wybierając pociąg {pkp}, kieruj się wariantami i rozkładem podanymi wyżej na tej stronie. Uwzględnij godzinę odjazdu pociągu {uz} i czas przesiadki."},"buy.t.s4":{"ru":"После покупки сохраните оба электронных билета в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть обидва електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save both e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz oba e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."},"buy.t.b1":{"ru":"Купить в приложении УЗ билет {uz}","uk":"Купити в застосунку УЗ квиток {uz}","en":"Buy the {uz} ticket in the UZ app","pl":"Kup w aplikacji UZ bilet {uz}"},"buy.t.b2":{"ru":"Купить на сайте PKP Intercity билет {pkp}","uk":"Купити на сайті PKP Intercity квиток {pkp}","en":"Buy the {pkp} ticket on PKP Intercity","pl":"Kup na stronie PKP Intercity bilet {pkp}"},"buy.note":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте PKP Intercity.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті PKP Intercity.","en":"Train schedules may change. Check the latest information in the UZ app and on the PKP Intercity website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie PKP Intercity."},"buy.t.s1z":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {uz} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите подходящий поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {uz} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {uz} and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose a suitable train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {uz} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},"buy.t.s2zk":{"ru":"Поезд {pkp} отправляется на следующие сутки, поэтому продажа билетов на него в приложении «Укрзалізниця» открывается на следующий день. Если хотите приобрести билет заранее, его можно отдельно купить в приложении словацкого перевозчика ZSSK. Как правило, билеты у ZSSK дешевле.","uk":"Поїзд {pkp} відправляється наступної доби, тому продаж квитків на нього в застосунку «Укрзалізниця» відкривається наступного дня. Якщо хочете придбати квиток заздалегідь, його можна окремо купити в застосунку словацького перевізника ZSSK. Зазвичай квитки в ZSSK дешевші.","en":"The {pkp} train departs the next day, so ticket sales for it in the Ukrzaliznytsia app open the following day. If you want to buy a ticket in advance, you can buy it separately in the app of the Slovak carrier ZSSK. ZSSK tickets are usually cheaper.","pl":"Pociąg {pkp} odjeżdża następnej doby, dlatego sprzedaż biletów na niego w aplikacji Ukrzaliznytsia rusza dzień później. Jeśli chcesz kupić bilet wcześniej, możesz kupić go osobno w aplikacji słowackiego przewoźnika ZSSK. Zwykle bilety ZSSK są tańsze."},"buy.d.s3z":{"ru":"Выберите место и оплатите билет банковской картой. Электронный билет появится в приложении. При посадке предъявите его вместе с паспортом.","uk":"Оберіть місце і сплатіть квиток банківською карткою. Електронний квиток з’явиться в застосунку. Під час посадки пред’явіть його разом із паспортом.","en":"Pick a seat and pay by bank card. The e-ticket will appear in the app. Show it with your passport when boarding.","pl":"Wybierz miejsce i zapłać kartą. E-bilet pojawi się w aplikacji. Przy wsiadaniu okaż go razem z paszportem."},"buy.d.s2v":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {dir} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Билеты на прямой поезд пользуются высоким спросом, поэтому рекомендуем покупать их сразу после начала продаж.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {dir} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. На прямий поїзд квитки користуються великим попитом, тому радимо купувати їх одразу після початку продажу.","en":"Open the Ukrzaliznytsia app, choose the route {dir} and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Tickets for the direct train are in high demand, so we recommend buying them as soon as sales open.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {dir} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Bilety na pociąg bezpośredni cieszą się dużym popytem, dlatego warto kupić je zaraz po otwarciu sprzedaży."},"buy.d.s2z":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {dir} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {dir} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route {dir} and the travel date. Sales open 20 days before departure at 08:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {dir} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego."},"buy.t.s2c":{"ru":"Билет на поезд {pkp} приобретите отдельно у румынского перевозчика CFR Călători — на официальном сайте bilete.cfrcalatori.ro.","uk":"Квиток на поїзд {pkp} придбайте окремо в румунського перевізника CFR Călători — на офіційному сайті bilete.cfrcalatori.ro.","en":"Buy the {pkp} ticket separately from the Romanian carrier CFR Călători, on bilete.cfrcalatori.ro.","pl":"Bilet na pociąg {pkp} kup osobno u rumuńskiego przewoźnika CFR Călători — na stronie bilete.cfrcalatori.ro."},"buy.t.b2c":{"ru":"Купить на сайте CFR билет {pkp}","uk":"Купити на сайті CFR квиток {pkp}","en":"Buy the {pkp} ticket on CFR","pl":"Kup na stronie CFR bilet {pkp}"},"buy.note.c":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте CFR Călători.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті CFR Călători.","en":"Train schedules may change. Check the latest information in the UZ app and on the CFR Călători website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie CFR Călători."},"transfer.h3":{"ru":"С пересадкой","uk":"З пересадкою","en":"With a transfer","pl":"Z przesiadką"},"buy.t.s1v":{"ru":"Откройте приложение «Укрзалізниця», выберите нужный поезд на украинском участке маршрута и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть потрібний поїзд на українській ділянці маршруту та вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the train you need on the Ukrainian part of the route and set the travel date. Sales open 20 days before departure, at 08:00 Kyiv time. Pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz odpowiedni pociąg na ukraińskim odcinku trasy i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Opłać bilet."},"buy.t.s2v":{"ru":"Билет на остальную часть пути приобретите отдельно, например у австрийского перевозчика ÖBB — на tickets.oebb.at или в приложении ÖBB Tickets.","uk":"Квиток на решту шляху придбайте окремо, наприклад в австрійського перевізника ÖBB — на tickets.oebb.at або в застосунку ÖBB Tickets.","en":"Buy the ticket for the rest of the journey separately, for example from the Austrian carrier ÖBB, on tickets.oebb.at or in the ÖBB Tickets app.","pl":"Bilet na resztę trasy kup osobno, na przykład u austriackiego przewoźnika ÖBB — na tickets.oebb.at lub w aplikacji ÖBB Tickets."},"buy.t.b1v":{"ru":"Купить билет в приложении УЗ","uk":"Купити квиток у застосунку УЗ","en":"Buy a ticket in the UZ app","pl":"Kup bilet w aplikacji UZ"},"buy.t.b2v":{"ru":"Купить билет на сайте ÖBB","uk":"Купити квиток на сайті ÖBB","en":"Buy a ticket on ÖBB","pl":"Kup bilet na stronie ÖBB"},"buy.h.s1":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {bud1} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {bud1} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {bud1} and the travel date. Sales open 20 days before departure, at 08:00 Kyiv time. Choose a train and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {bud1} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg i opłać bilet."},"buy.h.s2":{"ru":"Билет {bud2} можно приобрести у венгерского перевозчика MÁV — на jegy.mav.hu или в приложении MÁVPlusz, либо у австрийского перевозчика ÖBB — на tickets.oebb.at или в приложении ÖBB Tickets.","uk":"Квиток {bud2} можна придбати в угорського перевізника MÁV — на jegy.mav.hu або в застосунку MÁVPlusz, чи в австрійського перевізника ÖBB — на tickets.oebb.at або в застосунку ÖBB Tickets.","en":"You can buy the {bud2} ticket from the Hungarian carrier MÁV, on jegy.mav.hu or in the MÁVPlusz app, or from the Austrian carrier ÖBB, on tickets.oebb.at or in the ÖBB Tickets app.","pl":"Bilet {bud2} można kupić u węgierskiego przewoźnika MÁV — na jegy.mav.hu lub w aplikacji MÁVPlusz, albo u austriackiego przewoźnika ÖBB — na tickets.oebb.at lub w aplikacji ÖBB Tickets."},"buy.h.b1":{"ru":"Купить в приложении УЗ билет {bud1}","uk":"Купити в застосунку УЗ квиток {bud1}","en":"Buy the {bud1} ticket in the UZ app","pl":"Kup w aplikacji UZ bilet {bud1}"},"buy.h.b2":{"ru":"Купить на сайте MÁV билет {bud2}","uk":"Купити на сайті MÁV квиток {bud2}","en":"Buy the {bud2} ticket on MÁV","pl":"Kup na stronie MÁV bilet {bud2}"},"buy.h.b3":{"ru":"Купить на сайте ÖBB билет {bud2}","uk":"Купити на сайті ÖBB квиток {bud2}","en":"Buy the {bud2} ticket on ÖBB","pl":"Kup na stronie ÖBB bilet {bud2}"},"buy.t.s1vk":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {uz} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 028Л и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {uz} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 028Л і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {uz} and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 028Л and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {uz} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 028Л i opłać bilet."},"buy.t.s2vk":{"ru":"Купите билет на поезд {pkp} в приложении «Укрзалізниця». Также билет можно приобрести заранее у австрийского перевозчика ÖBB — на tickets.oebb.at или в приложении ÖBB Tickets. Но в таком случае он будет существенно дороже, чем в приложении «Укрзалізниця».","uk":"Придбайте квиток на поїзд {pkp} у застосунку «Укрзалізниця». Також квиток можна придбати заздалегідь в австрійського перевізника ÖBB — на tickets.oebb.at або в застосунку ÖBB Tickets. Але в такому разі він буде суттєво дорожчим, ніж у застосунку «Укрзалізниця».","en":"Buy the ticket for the {pkp} train in the Ukrzaliznytsia app. You can also buy a ticket in advance from the Austrian carrier ÖBB, on tickets.oebb.at or in the ÖBB Tickets app. In that case it will be considerably more expensive than in the Ukrzaliznytsia app.","pl":"Kup bilet na pociąg {pkp} w aplikacji Ukrzaliznytsia. Bilet można też kupić wcześniej u austriackiego przewoźnika ÖBB — na tickets.oebb.at lub w aplikacji ÖBB Tickets. W takim przypadku będzie jednak znacznie droższy niż w aplikacji Ukrzaliznytsia."},"buy.t.s1kv":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {uz} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите поезд 027К и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {uz} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть поїзд 027К і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {uz} and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose train 027К and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {uz} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz pociąg 027К i opłać bilet."},"buy.t.s2ov":{"ru":"Поезда {pkp} отправляются на следующие сутки, поэтому продажа билетов на них в приложении «Укрзалізниця» открывается на следующий день. Также билет можно приобрести заранее у австрийского перевозчика ÖBB — на tickets.oebb.at или в приложении ÖBB Tickets. Но в таком случае он будет существенно дороже, чем в приложении «Укрзалізниця».","uk":"Поїзди {pkp} відправляються наступної доби, тому продаж квитків на них у застосунку «Укрзалізниця» відкривається наступного дня. Також квиток можна придбати заздалегідь в австрійського перевізника ÖBB — на tickets.oebb.at або в застосунку ÖBB Tickets. Але в такому разі він буде суттєво дорожчим, ніж у застосунку «Укрзалізниця».","en":"The {pkp} trains depart the next day, so ticket sales for them in the Ukrzaliznytsia app open the following day. You can also buy a ticket in advance from the Austrian carrier ÖBB, on tickets.oebb.at or in the ÖBB Tickets app. In that case it will be considerably more expensive than in the Ukrzaliznytsia app.","pl":"Pociągi {pkp} odjeżdżają następnej doby, dlatego sprzedaż biletów na nie w aplikacji Ukrzaliznytsia rusza dzień później. Bilet można też kupić wcześniej u austriackiego przewoźnika ÖBB — na tickets.oebb.at lub w aplikacji ÖBB Tickets. W takim przypadku będzie jednak znacznie droższy niż w aplikacji Ukrzaliznytsia."},"buy.t.s2o":{"ru":"Билет на поезд {pkp} приобретите отдельно у австрийского перевозчика ÖBB — на официальном сайте tickets.oebb.at или в приложении ÖBB Tickets.","uk":"Квиток на поїзд {pkp} придбайте окремо в австрійського перевізника ÖBB — на офіційному сайті tickets.oebb.at або в застосунку ÖBB Tickets.","en":"Buy the {pkp} ticket separately from the Austrian carrier ÖBB, on tickets.oebb.at or in the ÖBB Tickets app.","pl":"Bilet na pociąg {pkp} kup osobno u austriackiego przewoźnika ÖBB — na stronie tickets.oebb.at lub w aplikacji ÖBB Tickets."},"buy.t.b2o":{"ru":"Купить на сайте ÖBB билет {pkp}","uk":"Купити на сайті ÖBB квиток {pkp}","en":"Buy the {pkp} ticket on ÖBB","pl":"Kup na stronie ÖBB bilet {pkp}"},"buy.note.o":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте ÖBB.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті ÖBB.","en":"Train schedules may change. Check the latest information in the UZ app and on the ÖBB website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie ÖBB."},"buy.t.s2z":{"ru":"Билет на поезд {pkp} можно купить в приложении «Укрзалізниця» или отдельно у словацкого перевозчика ZSSK в его приложении. Обычно у ZSSK билеты дешевле.","uk":"Квиток на поїзд {pkp} можна купити в застосунку «Укрзалізниця» або окремо в словацького перевізника ZSSK у його застосунку. Зазвичай у ZSSK квитки дешевші.","en":"You can buy the {pkp} ticket in the Ukrzaliznytsia app or separately from the Slovak carrier ZSSK in its app. Tickets from ZSSK are usually cheaper.","pl":"Bilet na pociąg {pkp} możesz kupić w aplikacji Ukrzaliznytsia lub osobno u słowackiego przewoźnika ZSSK w jego aplikacji. Zwykle u ZSSK bilety są tańsze."},"buy.t.b2z":{"ru":"Купить в приложении ZSSK билет {pkp}","uk":"Купити в застосунку ZSSK квиток {pkp}","en":"Buy the {pkp} ticket in the ZSSK app","pl":"Kup w aplikacji ZSSK bilet {pkp}"},"buy.note.z":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и в приложении ZSSK.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та в застосунку ZSSK.","en":"Train schedules may change. Check the latest information in the UZ app and in the ZSSK app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i w aplikacji ZSSK."},"buy.a.s1":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {dir} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 09:00 по киевскому времени.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {dir} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 09:00 за київським часом.","en":"Open the Ukrzaliznytsia app, choose the route {dir} and the travel date. Sales open 20 days before departure at 09:00 Kyiv time.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {dir} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 9:00 czasu kijowskiego."},"buy.a.s2":{"ru":"Нажмите «З пересадками» и в предложенном варианте по очереди выберите места для каждого поезда, затем оплатите оба билета в приложении.","uk":"Натисніть «З пересадками» і в запропонованому варіанті по черзі оберіть місця для кожного поїзда, а потім сплатіть обидва квитки в застосунку.","en":"Tap “З пересадками” (With transfers), then in the option offered pick seats for each train in turn and pay for both tickets in the app.","pl":"Naciśnij „З пересадками” (z przesiadkami), a w zaproponowanym wariancie po kolei wybierz miejsca w każdym pociągu i opłać oba bilety w aplikacji."},"buy.a.s3":{"ru":"После покупки сохраните электронные билеты в телефоне. Перед поездкой проверьте даты, время отправления и станции прибытия.","uk":"Після купівлі збережіть електронні квитки в телефоні. Перед поїздкою перевірте дати, час відправлення та станції прибуття.","en":"After buying, save the e-tickets on your phone. Before you travel, check the dates, departure times and arrival stations.","pl":"Po zakupie zapisz e-bilety w telefonie. Przed podróżą sprawdź daty, godziny odjazdu i stacje docelowe."},"buy.a.btn":{"ru":"Купить в приложении УЗ билеты {dir}","uk":"Купити в застосунку УЗ квитки {dir}","en":"Buy the {dir} tickets in the UZ app","pl":"Kup w aplikacji UZ bilety {dir}"},"buy.note.a":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ.","en":"Train schedules may change. Check the latest information in the UZ app.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ."},"buy.be.sC":{"ru":"Билеты {de} можно купить на немецком сайте bahn.de или в приложении DB Navigator.","uk":"Квитки {de} можна купити на німецькому сайті bahn.de або в застосунку DB Navigator.","en":"Tickets for {de} can be bought on the German website bahn.de or in the DB Navigator app.","pl":"Bilety na odcinek {de} kupisz na niemieckiej stronie bahn.de lub w aplikacji DB Navigator."},"buy.be.sT":{"ru":"Билеты {pl} можно купить на польском сайте PKP Intercity (intercity.pl), а {de} — на немецком сайте bahn.de или в приложении DB Navigator.","uk":"Квитки {pl} можна купити на польському сайті PKP Intercity (intercity.pl), а {de} — на німецькому сайті bahn.de або в застосунку DB Navigator.","en":"Tickets for {pl} can be bought on the Polish PKP Intercity website (intercity.pl), and for {de} on the German website bahn.de or in the DB Navigator app.","pl":"Bilety na odcinek {pl} kupisz na polskiej stronie PKP Intercity (intercity.pl), a na odcinek {de} — na niemieckiej stronie bahn.de lub w aplikacji DB Navigator."},"buy.be.sH":{"ru":"Билеты {pl} можно купить на польском сайте PKP Intercity (intercity.pl; кроме ночного поезда) и на немецком сайте bahn.de или в приложении DB Navigator.","uk":"Квитки {pl} можна купити на польському сайті PKP Intercity (intercity.pl; крім нічного поїзда) і на німецькому сайті bahn.de або в застосунку DB Navigator.","en":"Tickets for {pl} can be bought on the Polish PKP Intercity website (intercity.pl; except the night train) and on the German website bahn.de or in the DB Navigator app.","pl":"Bilety na odcinek {pl} kupisz na polskiej stronie PKP Intercity (intercity.pl; z wyjątkiem pociągu nocnego) oraz na niemieckiej stronie bahn.de lub w aplikacji DB Navigator."},"buy.be.bd":{"ru":"Купить на сайте DB билет {de}","uk":"Купити на сайті DB квиток {de}","en":"Buy the {de} ticket on DB","pl":"Kup na stronie DB bilet {de}"},"buy.note.be":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ, на сайте PKP Intercity и на сайте DB.","uk":"Графіки руху поїздів можуть змінитися, актуальну інформацію дивіться в застосунку УЗ, на сайті PKP Intercity та на сайті DB.","en":"Train schedules may change. Check the latest information in the UZ app, on the PKP Intercity website and on the DB website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ oraz na stronach PKP Intercity i DB."},"ix.title":{"ru":"Колія: поездом из Украины и в Украину","uk":"Колія: потягом з України та в Україну","en":"Koliya: by train from and to Ukraine","pl":"Koliya: pociągiem z Ukrainy i na Ukrainę"},"ix.h1":{"ru":"Поездом в Украину и из Украины","uk":"Потягом в Україну та з України","en":"By train to and from Ukraine","pl":"Pociągiem na Ukrainę i z Ukrainy"},"ix.lead":{"ru":"Маршруты, расписания, пересадки и покупка билетов в европейские страны.","uk":"Маршрути, розклади, пересадки та купівля квитків у європейські країни.","en":"Routes, timetables, transfers and ticket buying for European countries.","pl":"Trasy, rozkłady jazdy, przesiadki i zakup biletów do krajów europejskich."},"ix.fromUa":{"ru":"Из Украины →","uk":"З України →","en":"From Ukraine →","pl":"Z Ukrainy →"},"ix.toUa":{"ru":"← В Украину","uk":"← В Україну","en":"← To Ukraine","pl":"← Na Ukrainę"},"ix.popular":{"ru":"Популярные маршруты","uk":"Популярні маршрути","en":"Popular routes","pl":"Popularne trasy"},"ix.how.h":{"ru":"Как пользоваться сайтом","uk":"Як користуватися сайтом","en":"How to use the site","pl":"Jak korzystać z serwisu"},"ix.how1":{"ru":"Выберите направление и найдите подходящий маршрут.","uk":"Оберіть напрям і знайдіть відповідний маршрут.","en":"Choose a direction and find a suitable route.","pl":"Wybierz kierunek i znajdź odpowiednią trasę."},"ix.how2":{"ru":"Ознакомьтесь с расписанием, пересадками и временем в пути.","uk":"Ознайомтеся з розкладом, пересадками та часом у дорозі.","en":"Check the timetable, transfers and travel time.","pl":"Sprawdź rozkład jazdy, przesiadki i czas podróży."},"ix.how3":{"ru":"Узнайте, где купить билеты на каждый участок маршрута.","uk":"Дізнайтеся, де купити квитки на кожну ділянку маршруту.","en":"Find out where to buy tickets for each part of the journey.","pl":"Dowiedz się, gdzie kupić bilety na każdy odcinek trasy."},"ix.help.h":{"ru":"Справочная Укрзализныци","uk":"Довідкова Укрзалізниці","en":"Ukrzaliznytsia information line","pl":"Infolinia Ukrzaliznyci"},"ix.help.p":{"ru":"Бесплатно с украинских номеров.","uk":"Безкоштовно з українських номерів.","en":"Free from Ukrainian numbers.","pl":"Bezpłatnie z numerów ukraińskich."},"ix.help.b1":{"ru":"График работы касс","uk":"Графік роботи кас","en":"Ticket office hours","pl":"Godziny pracy kas"},"ix.help.b2":{"ru":"Список задерживающихся рейсов","uk":"Список поїздів, що затримуються","en":"List of delayed trains","pl":"Lista opóźnionych pociągów"},"ix.fly.h":{"ru":"Прилететь самолётом ✈️","uk":"Прилетіти літаком ✈️","en":"Arrive by air ✈️","pl":"Przylot samolotem ✈️"},"ix.fly.p":{"ru":"В Украину можно добраться из любой страны. Выберите рейс до одного из аэропортов, откуда удобные пересадки на наши поезда.","uk":"В Україну можна дістатися з будь-якої країни. Оберіть рейс до одного з аеропортів, звідки зручні пересадки на наші поїзди.","en":"You can reach Ukraine from any country. Pick a flight to one of the airports with convenient connections to our trains.","pl":"Na Ukrainę można dotrzeć z każdego kraju. Wybierz lot do jednego z lotnisk, skąd są wygodne przesiadki na nasze pociągi."},"ix.buy.h":{"ru":"Купить билеты на УЗ","uk":"Купити квитки на УЗ","en":"Buy UZ tickets","pl":"Kup bilety UZ"},"ix.buy.b1":{"ru":"Приложение Укрзализныци","uk":"Застосунок Укрзалізниці","en":"Ukrzaliznytsia app","pl":"Aplikacja Ukrzaliznyci"},"ix.buy.b2":{"ru":"Сайт УЗ","uk":"Сайт УЗ","en":"UZ website","pl":"Strona UZ"},"ix.all":{"ru":"← Все направления","uk":"← Усі напрями","en":"← All directions","pl":"← Wszystkie kierunki"},"ix.soon":{"ru":"Маршруты для этого направления скоро появятся.","uk":"Маршрути для цього напряму скоро з’являться.","en":"Routes for this direction are coming soon.","pl":"Trasy dla tego kierunku pojawią się wkrótce."},"ix.one":{"ru":"⚡ {t} →","uk":"⚡ {t} →","en":"⚡ {t} →","pl":"⚡ {t} →"},"ix.dirTitle":{"ru":"{t} поездом | Колія","uk":"{t} потягом | Колія","en":"{t} by train | Koliya","pl":"{t} pociągiem | Koliya"},"ix.rtOut":{"ru":"Из Украины в {nom}","uk":"З України до {gen}","en":"From Ukraine to {nom}","pl":"Z Ukrainy do {gen}"},"ix.rtIn":{"ru":"Из {gen} в Украину","uk":"З {gen} в Україну","en":"From {nom} to Ukraine","pl":"Z {gen} na Ukrainę"},"ix.leadDir":{"ru":"Прямые поезда и варианты с пересадкой","uk":"Прямі поїзди та варіанти з пересадкою","en":"Direct trains and options with a transfer","pl":"Pociągi bezpośrednie i połączenia z przesiadką"},"ix.nav":{"ru":"Направление","uk":"Напрям","en":"Direction","pl":"Kierunek"},"ix.countries.h":{"ru":"Выберите страну","uk":"Оберіть країну","en":"Choose a country","pl":"Wybierz kraj"},"ix.info.h":{"ru":"Полезная информация","uk":"Корисна інформація","en":"Useful information","pl":"Przydatne informacje"},"ix.more":{"ru":"Ещё маршруты ({n})","uk":"Ще маршрути ({n})","en":"More routes ({n})","pl":"Więcej tras ({n})"},"transfer.h2":{"ru":"С пересадкой {xin}","uk":"З пересадкою {xin}","en":"With a transfer {xin}","pl":"Z przesiadką {xin}"},"border.after":{"ru":"После прибытия в Перемышль происходит пограничный контроль","uk":"Після прибуття до Перемишля відбувається прикордонний контроль","en":"Border control takes place in Przemyśl after arrival","pl":"Po przyjeździe do Przemyśla odbywa się kontrola graniczna"},"border.before":{"ru":"Перед отправлением из Перемышля происходит пограничный контроль","uk":"Перед відправленням із Перемишля відбувається прикордонний контроль","en":"Border control takes place in Przemyśl before departure","pl":"Przed odjazdem z Przemyśla odbywa się kontrola graniczna"},"buy.t.s2m":{"ru":"Билет на поезд {pkp} приобретите отдельно у венгерского перевозчика MÁV — на официальном сайте jegy.mav.hu или в приложении MÁVPlusz.","uk":"Квиток на поїзд {pkp} придбайте окремо в угорського перевізника MÁV — на офіційному сайті jegy.mav.hu або в застосунку MÁVPlusz.","en":"Buy the {pkp} ticket separately from the Hungarian carrier MÁV, on jegy.mav.hu or in the MÁVPlusz app.","pl":"Bilet na pociąg {pkp} kup osobno u węgierskiego przewoźnika MÁV — na stronie jegy.mav.hu lub w aplikacji MÁVPlusz."},"buy.t.b2m":{"ru":"Купить на сайте MÁV билет {pkp}","uk":"Купити на сайті MÁV квиток {pkp}","en":"Buy the {pkp} ticket on MÁV","pl":"Kup na stronie MÁV bilet {pkp}"},"buy.note.m":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ и на сайте MÁV.","uk":"Графіки руху поїздів можуть змінюватися, актуальну інформацію дивіться в застосунку УЗ та на сайті MÁV.","en":"Train schedules may change. Check the latest information in the UZ app and on the MÁV website.","pl":"Rozkłady jazdy mogą ulec zmianie. Aktualne informacje znajdziesz w aplikacji UZ i na stronie MÁV."},"buy.t.s2mo":{"ru":"Поезда {pkp} отправляются на следующие сутки, поэтому продажа билетов на них в приложении «Укрзалізниця» открывается на следующий день. Также билет можно приобрести заранее у венгерского перевозчика MÁV — на jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Поїзди {pkp} відправляються наступної доби, тому продаж квитків на них у застосунку «Укрзалізниця» відкривається наступного дня. Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"Trains {pkp} depart the next day, so ticket sales for them in the Ukrzaliznytsia app open the following day. You can also buy the ticket in advance from the Hungarian carrier MÁV, on jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Pociągi {pkp} odjeżdżają następnego dnia, dlatego sprzedaż biletów na nie w aplikacji Ukrzaliznytsia rusza dzień później. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na jegy.mav.hu lub w aplikacji MÁVPlusz. Zazwyczaj bilety MÁV są tańsze."},"buy.t.s2mi":{"ru":"Купите билет на поезд {pkp} в приложении «Укрзалізниця». Также билет можно приобрести заранее у венгерского перевозчика MÁV — на официальном сайте jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Придбайте квиток на поїзд {pkp} у застосунку «Укрзалізниця». Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на офіційному сайті jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"Buy the {pkp} ticket in the Ukrzaliznytsia app. You can also buy the ticket in advance from the Hungarian carrier MÁV, on the official site jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Kup bilet na pociąg {pkp} w aplikacji Ukrzaliznytsia. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na oficjalnej stronie jegy.mav.hu lub w aplikacji MÁVPlusz. Zazwyczaj bilety MÁV są tańsze."},"buy.x.s1":{"ru":"Откройте приложение «Укрзалізниця», выберите нужный поезд на украинском участке маршрута ({xu}) и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть потрібний поїзд на українській ділянці маршруту ({xu}) та вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the train you need on the Ukrainian part of the route ({xu}) and set the travel date. Sales open 20 days before departure, at 08:00 Kyiv time. Pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz odpowiedni pociąg na ukraińskim odcinku trasy ({xu}) i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Opłać bilet."},"buy.x.s2o":{"ru":"Поезда на венгерском участке ({xp}) отправляются на следующие сутки, поэтому продажа билетов на них в приложении «Укрзалізниця» открывается на следующий день. Также билет можно приобрести заранее у венгерского перевозчика MÁV — на jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Поїзди на угорській ділянці ({xp}) відправляються наступної доби, тому продаж квитків на них у застосунку «Укрзалізниця» відкривається наступного дня. Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"Trains on the Hungarian section ({xp}) depart the next day, so ticket sales for them in the Ukrzaliznytsia app open the following day. You can also buy the ticket in advance from the Hungarian carrier MÁV, on jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Pociągi na odcinku węgierskim ({xp}) odjeżdżają następnego dnia, dlatego sprzedaż biletów na nie w aplikacji Ukrzaliznytsia rusza dzień później. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na jegy.mav.hu lub w aplikacji MÁVPlusz. Zazwyczaj bilety MÁV są tańsze."},"buy.x.s2i":{"ru":"Купите билеты на поезда {xp} в приложении «Укрзалізниця». Также билет можно приобрести заранее у венгерского перевозчика MÁV — на официальном сайте jegy.mav.hu или в приложении MÁVPlusz. Как правило, билеты у MÁV дешевле.","uk":"Придбайте квитки на поїзди {xp} у застосунку «Укрзалізниця». Також квиток можна придбати заздалегідь в угорського перевізника MÁV — на офіційному сайті jegy.mav.hu або в застосунку MÁVPlusz. Як правило, квитки в MÁV дешевші.","en":"Buy the tickets for the trains {xp} in the Ukrzaliznytsia app. You can also buy the ticket in advance from the Hungarian carrier MÁV, on the official site jegy.mav.hu or in the MÁVPlusz app. MÁV tickets are usually cheaper.","pl":"Kup bilety na pociągi {xp} w aplikacji Ukrzaliznytsia. Bilet można też kupić wcześniej u węgierskiego przewoźnika MÁV — na oficjalnej stronie jegy.mav.hu lub w aplikacji MÁVPlusz. Zazwyczaj bilety MÁV są tańsze."},"buy.x.b1":{"ru":"Купить билеты в приложении УЗ","uk":"Купити квитки в застосунку УЗ","en":"Buy tickets in the UZ app","pl":"Kup bilety w aplikacji UZ"},"buy.x.b2":{"ru":"Купить билеты на сайте MÁV","uk":"Купити квитки на сайті MÁV","en":"Buy tickets on MÁV","pl":"Kup bilety na stronie MÁV"},"buy.x.s2z":{"ru":"Билеты на поезда {xp} можно купить в приложении «Укрзалізниця» или отдельно у словацкого перевозчика ZSSK в его приложении. Обычно у ZSSK билеты дешевле.","uk":"Квитки на поїзди {xp} можна купити в застосунку «Укрзалізниця» або окремо в словацького перевізника ZSSK у його застосунку. Зазвичай у ZSSK квитки дешевші.","en":"You can buy tickets for the trains {xp} in the Ukrzaliznytsia app or separately from the Slovak carrier ZSSK in its app. Tickets from ZSSK are usually cheaper.","pl":"Bilety na pociągi {xp} możesz kupić w aplikacji Ukrzaliznytsia lub osobno u słowackiego przewoźnika ZSSK w jego aplikacji. Zwykle u ZSSK bilety są tańsze."},"buy.x.b2z":{"ru":"Купить билеты в приложении ZSSK","uk":"Купити квитки в застосунку ZSSK","en":"Buy tickets in the ZSSK app","pl":"Kup bilety w aplikacji ZSSK"},"buy.m.s1":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {uz} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в 08:00 по киевскому времени. Выберите нужный поезд и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {uz} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о 08:00 за київським часом. Оберіть потрібний поїзд і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {uz} and the travel date. Sales open 20 days before departure at 08:00 Kyiv time. Choose the train you need and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {uz} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o 08:00 czasu kijowskiego. Wybierz odpowiedni pociąg i opłać bilet."},"buy.t.s2cd":{"ru":"Билет {pkp} на поезда EC и IC приобретите отдельно у чешского перевозчика České dráhy (ČD) — на cd.cz или в приложении ČD My Train (Můj vlak).","uk":"Квиток {pkp} на поїзди EC та IC придбайте окремо в чеського перевізника České dráhy (ČD) — на cd.cz або в застосунку ČD My Train (Můj vlak).","en":"Buy the {pkp} ticket for EC and IC trains separately from the Czech carrier České dráhy (ČD), on cd.cz or in the ČD My Train (Můj vlak) app.","pl":"Bilet {pkp} na pociągi EC i IC kup osobno u czeskiego przewoźnika České dráhy (ČD) — na cd.cz lub w aplikacji ČD My Train (Můj vlak)."},"buy.t.b2cd":{"ru":"Купить на сайте ČD билет {pkp}","uk":"Купити на сайті ČD квиток {pkp}","en":"Buy the {pkp} ticket on ČD","pl":"Kup bilet {pkp} na stronie ČD"},"buy.note.cz":{"ru":"Графики движения поездов могут измениться, актуальную информацию смотрите в приложении УЗ, в приложении ČD My Train и на сайте RegioJet.","uk":"Графіки руху поїздів можуть змінитися, актуальну інформацію дивіться в застосунку УЗ, у застосунку ČD My Train та на сайті RegioJet.","en":"Train schedules may change. Check the latest information in the UZ app, in the ČD My Train app and on the RegioJet website.","pl":"Rozkłady jazdy mogą się zmienić, aktualne informacje sprawdź w aplikacji UZ, w aplikacji ČD My Train i na stronie RegioJet."},"buy.t.s2rj":{"ru":"Билет {pkp} на поезд RJ приобретите отдельно у чешского перевозчика RegioJet — на официальном сайте regiojet.cz или в приложении RegioJet.","uk":"Квиток {pkp} на поїзд RJ придбайте окремо в чеського перевізника RegioJet — на офіційному сайті regiojet.cz або в застосунку RegioJet.","en":"Buy the {pkp} ticket for the RJ train separately from the Czech carrier RegioJet, on regiojet.cz or in the RegioJet app.","pl":"Bilet {pkp} na pociąg RJ kup osobno u czeskiego przewoźnika RegioJet — na stronie regiojet.cz lub w aplikacji RegioJet."},"buy.t.b2rj":{"ru":"Купить на сайте RegioJet билет {pkp}","uk":"Купити на сайті RegioJet квиток {pkp}","en":"Buy the {pkp} ticket on RegioJet","pl":"Kup bilet {pkp} na stronie RegioJet"},"buy.c.h":{"ru":"С пересадкой {xin}","uk":"З пересадкою {xin}","en":"With a transfer {xin}","pl":"Z przesiadką {xin}"},"buy.c.s1":{"ru":"Откройте приложение «Укрзалізниця», выберите маршрут {uz} и укажите дату поездки. Продажа билетов открывается за 20 суток до отправления, в {open} по киевскому времени. Выберите поезд {train} и оплатите билет.","uk":"Відкрийте застосунок «Укрзалізниця», оберіть маршрут {uz} і вкажіть дату поїздки. Продаж квитків відкривається за 20 діб до відправлення, о {open} за київським часом. Оберіть поїзд {train} і сплатіть квиток.","en":"Open the Ukrzaliznytsia app, choose the route {uz} and the travel date. Sales open 20 days before departure at {open} Kyiv time. Choose train {train} and pay for the ticket.","pl":"Otwórz aplikację Ukrzaliznytsia, wybierz trasę {uz} i datę podróży. Sprzedaż biletów rusza na 20 dni przed odjazdem o {open} czasu kijowskiego. Wybierz pociąg {train} i opłać bilet."},"buy.c.dt":{"ru":"отправление из {a} {t1}, прибытие в {b} {t2}","uk":"відправлення з {a} {t1}, прибуття до {b} {t2}","en":"departure from {a} {t1}, arrival in {b} {t2}","pl":"odjazd z {a} {t1}, przyjazd do {b} {t2}"},"cn.pl":{"uk":"Польща","en":"Poland","pl":"Polska"},"cn.pl.gen":{"uk":"Польщі","pl":"Polski"},"cn.sk":{"uk":"Словаччина","en":"Slovakia","pl":"Słowacja"},"cn.sk.gen":{"uk":"Словаччини","pl":"Słowacji"},"cn.hu":{"uk":"Угорщина","en":"Hungary","pl":"Węgry"},"cn.hu.gen":{"uk":"Угорщини","pl":"Węgier"},"cn.ro":{"uk":"Румунія","en":"Romania","pl":"Rumunia"},"cn.ro.gen":{"uk":"Румунії","pl":"Rumunii"},"cn.md":{"uk":"Молдова","en":"Moldova","pl":"Mołdawia"},"cn.md.gen":{"uk":"Молдови","pl":"Mołdawii"},"cn.at":{"uk":"Австрія","en":"Austria","pl":"Austria"},"cn.at.gen":{"uk":"Австрії","pl":"Austrii"},"cn.cz":{"uk":"Чехія","en":"Czechia","pl":"Czechy"},"cn.cz.gen":{"uk":"Чехії","pl":"Czech"},"cn.de":{"uk":"Німеччина","en":"Germany","pl":"Niemcy"},"cn.de.gen":{"uk":"Німеччини","pl":"Niemiec"}}$j$::jsonb) as t(k, v)
on conflict (key) do nothing;

-- 2. Станции: формы «в Хелме» / «у Хелмі» / «w Chełmie» (названия uk/en/pl уже есть в stations)
alter table stations add column if not exists in_ru text;
alter table stations add column if not exists in_uk text;
alter table stations add column if not exists in_pl text;

-- сайт читает названия станций без входа
drop policy if exists stations_read_anon on stations;
create policy stations_read_anon on stations for select to anon using (true);

-- Заполняются только пустые поля: то, что уже есть в базе, остаётся как есть.
-- Станция ищется по русскому названию или по псевдониму; если её нет совсем, создаётся новая.
do $$
declare r record; sid bigint;
begin
