update route_pages r set texts = (
  select jsonb_object_agg(l, coalesce(seed.t->l, '{}'::jsonb) || coalesce(r.texts->l, '{}'::jsonb))
  from unnest(array['ru','uk','en','pl']) as l
) from seed where seed.id = r.id;

